  "questions": [
    {
      "question": "Quelle est la définition d'un incident de sécurité selon le document ?",
      "options": [
        "Un événement qui perturbe le fonctionnement normal des opérations.",
        "Une violation des procédures établies, une menace ou un compromis à la sécurité des personnes, des biens ou des informations.",
        "Un événement impliquant des dommages matériels importants.",
        "Un signalement d'anomalie par un agent de sécurité."
      ],
      "answer": 1,
      "explanation": "La définition d'un incident de sécurité est donnée au début du document : tout événement qui menace ou compromet la sécurité des personnes, des biens ou des informations, ou qui constitue une violation des procédures établies ou perturbe le fonctionnement normal des opérations."
    },
    {
      "question": "À qui un agent doit-il signaler un incident de niveau 2 ?",
      "options": [
        "Le responsable sécurité",
        "La direction générale",
        "Son supérieur hiérarchique",
        "Les forces de l'ordre"
      ],
      "answer": 0,
      "explanation": "Pour un incident de niveau 2 (tentative d'intrusion, vol mineur), le délai de rapport est de 1 heure et les destinataires sont le responsable sécurité."
    },
    {
      "question": "Un agent constate une porte non verrouillée dans son bureau. Quel niveau d'incident doit-il déclarer ?",
      "options": [
        "Niveau 3",
        "Niveau 1",
        "Niveau 4",
        "Niveau 2"
      ],
      "answer": 1,
      "explanation": "Une porte non verrouillée est considérée comme une anomalie mineure, classée au niveau 1, qui doit être signalée à son supérieur hiérarchique à la fin de la journée."
    }
  ]
}

