messages.content:
{
  "questions": [
    {
      "question": "Selon le GAFI, qu'est-ce qu'un actif virtuel ?",
      "options": [
        "Une monnaie fiduciaire émise par un gouvernement",
        "Une représentation numérique de valeur qui peut être échangée ou transférée numériquement",
        "Un bien immobilier détenu virtuellement",
        "Un type d'énergie renouvelable"
      ],
      "answer": 1,
      "explanation": "La définition du GAFI stipule qu'un actif virtuel est une représentation numérique de valeur qui peut être échangée ou transférée numériquement."
    },
    {
      "question": "Quelles sont les deux principales préoccupations exprimées par le GAFI concernant les actifs virtuels ?",
      "options": [
        "Le vol et la perte de données",
        "La sécurité des plateformes d'échange",
        "Les risques liés au blanchiment d'argent et au financement du terrorisme",
        "L'impact environnemental de la production d'actifs virtuels"
      ],
      "answer": 2,
      "explanation": "Le GAFI met en garde contre les risques de blanchiment d'argent et de financement du terrorisme liés aux actifs virtuels."
    },
    {
      "question": "Un prestataire de services sur actifs virtuels (PSAV) doit obligatoirement effectuer quoi ?",
      "options": [
        "Organiser des formations sur la sécurité des actifs numériques",
        "Émettre des rapports annuels sur les transactions effectuées",
        "Identifier et vérifier les clients avant de leur fournir des services",
        "Utiliser une technologie de consensus comme PBFT pour sécuriser ses transactions"
      ],
      "answer": 2,
      "explanation": "Le GAFI exige que les PSAV identifient et vérifient leurs clients (KYC) avant de leur fournir des services."
    }
  ]
}

